const items = $input.all();

return items.map(item => {
  const output = item.json.text;

  if (!output) {
    throw new Error("Gemini did not return any text output.");
  }

  let cleaned = output.trim();

  // Remove markdown code fences if Gemini adds them
  cleaned = cleaned.replace(/^```json\s*/i, "");
  cleaned = cleaned.replace(/^```\s*/i, "");
  cleaned = cleaned.replace(/\s*```$/i, "");

  let parsed;

  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      "Gemini returned invalid JSON. Raw output: " + output
    );
  }

  return {
    json: parsed
  };
});

const input = $input.first().json;

const supplierObligations = input.supplier_obligations || [];
const customerReceivables = input.customer_receivables || [];

const today = new Date();
today.setHours(0, 0, 0, 0);

function calculateDaysUntil(dateString) {
  if (!dateString) return null;

  const date = new Date(dateString);
  if (isNaN(date.getTime())) return null;

  date.setHours(0, 0, 0, 0);

  return Math.ceil(
    (date.getTime() - today.getTime()) / (1000 * 60 * 60 * 24)
  );
}

const suppliers = supplierObligations.map(item => {
  const daysUntilDue = item.due_date
    ? calculateDaysUntil(item.due_date)
    : item.credit_days ?? null;

  return {
    ...item,
    days_until_due: daysUntilDue,
    timing_basis: item.due_date
      ? "calculated from supplied due date"
      : "relative credit period supplied, exact due date not confirmed"
  };
});

const customers = customerReceivables.map(item => {
  const daysUntilCollection = item.expected_collection_date
    ? calculateDaysUntil(item.expected_collection_date)
    : item.credit_days ?? null;

  return {
    ...item,
    days_until_collection: daysUntilCollection,
    timing_basis: item.expected_collection_date
      ? "calculated from supplied collection date"
      : "relative customer payment period supplied, exact collection date not confirmed"
  };
});

const totalSupplierAmount = suppliers.reduce(
  (sum, item) => sum + (Number(item.amount) || 0),
  0
);

const totalCustomerReceivable = customers.reduce(
  (sum, item) => sum + (Number(item.amount) || 0),
  0
);

const earliestSupplierDue = suppliers
  .map(item => item.days_until_due)
  .filter(value => value !== null)
  .sort((a, b) => a - b)[0] ?? null;

const earliestCustomerCollection = customers
  .map(item => item.days_until_collection)
  .filter(value => value !== null)
  .sort((a, b) => a - b)[0] ?? null;

const timingGap =
  earliestSupplierDue !== null &&
  earliestCustomerCollection !== null
    ? earliestCustomerCollection - earliestSupplierDue
    : null;

let timingStatus = "CANNOT DETERMINE";

if (timingGap !== null) {
  if (timingGap < 0) {
    timingStatus = "CUSTOMER COLLECTION EXPECTED BEFORE SUPPLIER PAYMENT";
  } else if (timingGap === 0) {
    timingStatus = "SAME-DAY TIMING";
  } else {
    timingStatus = "SUPPLIER PAYMENT DUE BEFORE CUSTOMER COLLECTION";
  }
}

return [
  {
    json: {
      ...input,

      timing_analysis: {
        analysis_date: today.toISOString().split("T")[0],

        supplier_obligations: suppliers,

        customer_receivables: customers,

        total_supplier_amount: totalSupplierAmount,

        total_customer_receivable: totalCustomerReceivable,

        earliest_supplier_due_days: earliestSupplierDue,

        earliest_customer_collection_days: earliestCustomerCollection,

        timing_gap_days: timingGap,

        timing_status: timingStatus
      }
    }
  }
];

const input = $input.first().json;

let output = input.text;

if (typeof output !== "string") {
  output = JSON.stringify(output);
}

let cleaned = output.trim();

// Remove markdown code fences if Gemini adds them
cleaned = cleaned.replace(/^```json\s*/i, "");
cleaned = cleaned.replace(/^```\s*/i, "");
cleaned = cleaned.replace(/\s*```$/i, "");

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    "Gemini returned invalid JSON. Raw output: " + output
  );
}

return [
  {
    json: parsed
  }
];

const data = $input.first().json;

const supplierObligations = data.timing_analysis?.supplier_obligations
  || data.supplier_obligations
  || [];

const customerReceivables = data.timing_analysis?.customer_receivables
  || data.customer_receivables
  || [];

const supplierAmount = supplierObligations.reduce(
  (sum, item) => sum + (Number(item.amount) || 0),
  0
);

const customerAmount = customerReceivables.reduce(
  (sum, item) => sum + (Number(item.amount) || 0),
  0
);

const knownCustomerAmount = customerReceivables
  .filter(item => item.credit_days !== null)
  .reduce(
    (sum, item) => sum + (Number(item.amount) || 0),
    0
  );

const unknownCustomerAmount = customerReceivables
  .filter(item => item.credit_days === null)
  .reduce(
    (sum, item) => sum + (Number(item.amount) || 0),
    0
  );

const earliestSupplierDue =
  data.timing_analysis?.earliest_supplier_due_days
  ?? supplierObligations
    .map(item => item.credit_days)
    .filter(v => v !== null)
    .sort((a, b) => a - b)[0]
  ?? null;

const earliestCustomerCollection =
  data.timing_analysis?.earliest_customer_collection_days
  ?? customerReceivables
    .map(item => item.credit_days)
    .filter(v => v !== null)
    .sort((a, b) => a - b)[0]
  ?? null;

let knownTimingGap = null;

if (
  earliestSupplierDue !== null &&
  earliestCustomerCollection !== null
) {
  knownTimingGap =
    earliestCustomerCollection - earliestSupplierDue;
}

let riskLevel = "UNKNOWN";

if (knownTimingGap !== null) {
  if (knownTimingGap < 0) {
    riskLevel = "LOW";
  } else if (knownTimingGap === 0) {
    riskLevel = "MEDIUM";
  } else {
    riskLevel = "HIGH";
  }
}

return [
  {
    json: {
      ...data,

      cash_flow_analysis: {
        total_supplier_obligations: supplierAmount,
        total_customer_receivables: customerAmount,
        known_customer_receivables: knownCustomerAmount,
        unknown_customer_receivables: unknownCustomerAmount,

        known_timing_gap_days: knownTimingGap,

        timing_risk: riskLevel,

        cash_flow_observation:
          unknownCustomerAmount > 0
            ? `₹${unknownCustomerAmount} of customer receivables have unconfirmed payment timing.`
            : "All customer payment timing is known."
      }
    }
  }
];
